import AVFoundation
import os

/// Native port of the Earth MIDI layers (js/audio.js) for platforms without WebKit (Apple TV).
/// Oscillators, filters and noise rendered live in one AVAudioSourceNode. No samples, nothing generated by a model.
/// All 13 layers: quakes, solar wind pad, ocean surf, X-ray shimmer + flare bells, jet stream wind, tides drone,
/// planet chord, space station, fires/storms/volcanoes, magnetosphere, air, sunrise chorus, Pulse drums + bass.
final class NativeSynth {
    let engine = AVAudioEngine()
    private var source: AVAudioSourceNode!
    private let reverb = AVAudioUnitReverb()
    private let limiter: AVAudioUnitEffect
    let dsp: SynthDSP
    private var room = "hall"
    private var fixedWet: Double = -1

    init() {
        let out = engine.outputNode.outputFormat(forBus: 0)
        let sr = out.sampleRate > 0 ? out.sampleRate : 48000
        dsp = SynthDSP(sampleRate: sr)
        let desc = AudioComponentDescription(componentType: kAudioUnitType_Effect, componentSubType: kAudioUnitSubType_PeakLimiter,
                                             componentManufacturer: kAudioUnitManufacturer_Apple, componentFlags: 0, componentFlagsMask: 0)
        limiter = AVAudioUnitEffect(audioComponentDescription: desc)
        let fmt = AVAudioFormat(standardFormatWithSampleRate: sr, channels: 2)!
        let dsp = self.dsp
        source = AVAudioSourceNode(format: fmt) { _, _, frames, abl -> OSStatus in
            let buf = UnsafeMutableAudioBufferListPointer(abl)
            guard buf.count >= 2, let l = buf[0].mData?.assumingMemoryBound(to: Float.self),
                  let r = buf[1].mData?.assumingMemoryBound(to: Float.self) else { return noErr }
            dsp.render(l, r, Int(frames))
            return noErr
        }
        reverb.loadFactoryPreset(.largeHall2)
        reverb.wetDryMix = 32
        engine.attach(source); engine.attach(reverb); engine.attach(limiter)
        engine.connect(source, to: reverb, format: fmt)
        engine.connect(reverb, to: limiter, format: fmt)
        engine.connect(limiter, to: engine.mainMixerNode, format: fmt)
        engine.mainMixerNode.outputVolume = 0.9
    }

    func start() throws {
        #if os(iOS) || os(tvOS)
        try AVAudioSession.sharedInstance().setCategory(.playback, mode: .default, options: [])
        try AVAudioSession.sharedInstance().setActive(true)
        #endif
        if !engine.isRunning { try engine.start() }
        dsp.setMaster(1)
    }
    func stop() {
        dsp.setMaster(0)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { [weak self] in
            guard let self, self.dsp.masterTarget == 0 else { return }
            self.engine.pause()
        }
    }
    /// Producer → Space: the room type (js ROOMS) and a fixed wet amount (−1 = follow the moon, like the site).
    func setRoom(type: String, wet: Double) {
        fixedWet = wet
        guard type != room else { return }
        room = type
        let preset: AVAudioUnitReverbPreset = switch type {
        case "plate": .plate
        case "room": .mediumRoom
        case "cathedral": .cathedral
        case "cave": .largeChamber
        case "space": .largeHall2
        default: .largeHall2
        }
        reverb.loadFactoryPreset(preset)
    }
    /// Moon illumination 0…1 → reverb amount (site: 0.38…0.85 send), unless the producer fixed it
    func setRoom(moon: Double) {
        let base = fixedWet >= 0 ? mapv(fixedWet, 0, 1, 10, 60) : mapv(moon, 0, 1, 24, 46)
        reverb.wetDryMix = Float(room == "space" ? min(80, base * 1.35) : base)
    }
}

// MARK: - DSP

/// Layer order used by the engine (js PAN_KEYS)
enum Layer {
    static let keys: [Character] = ["q", "s", "o", "x", "w", "t", "c", "r", "i", "e", "g", "a", "u"]
    static func ix(_ k: Character) -> Int { keys.firstIndex(of: k) ?? 0 }
}

/// A 16-step groove (js/groove.js GROOVES): one byte per 16th note per lane.
struct GrooveSteps {
    var k = [UInt8](repeating: 46, count: 16), s = [UInt8](repeating: 46, count: 16)
    var h = [UInt8](repeating: 46, count: 16), b = [UInt8](repeating: 46, count: 16)
    var bl = 1.6, trim = 1.0
    init() {}
    init(k: String, s: String, h: String, b: String, bl: Double, trim: Double = 1) {
        func a(_ x: String) -> [UInt8] { let u = Array(x.utf8); return (0..<16).map { $0 < u.count ? u[$0] : 46 } }
        self.k = a(k); self.s = a(s); self.h = a(h); self.b = a(b); self.bl = bl; self.trim = trim
    }
}

/// Parameters the control loop sets; the audio thread glides toward them (like setTargetAtTime).
struct SynthTargets {
    var padCut = 800.0, padQ = 2.0, padLfoRate = 0.07, padGain = 0.0
    var padFreqs = [Double](repeating: 110, count: 4)
    var padVoiceGain = [Double](repeating: 0.05, count: 4)
    var padWave = 0 // 0 saw, 1 hollow (square), 2 soft (triangle), 3 glass (sine)
    var surfGain = 0.0, surfRate = 0.1, surfBP = 700.0
    var shimGain = 0.0, shimBP = 4000.0
    var windGain = 0.0, windBP1 = 600.0, windBP2 = 1100.0, windLfo = 0.09
    var tideGain = 0.0, tideDetune = 0.0
    var choirGain = 0.0
    var choirFreqs = [Double](repeating: 220, count: 10)
    var choirVoice = [Double](repeating: 1, count: 10) // per-city weight (Zones)
    var mute = Set<Character>()
    /// Per-layer level after mute/solo, in Layer.keys order
    var vol = [Double](repeating: 1, count: 13)
    // tuning, for the notes the audio thread picks itself (embers, glitter, bass)
    var root = 50
    var scale = Music.majPent
    // space station beacon
    var issFreq = 440.0, issGain = 0.0, issPan = 0.0
    // natural events
    var volcanoGains = [Double](repeating: 0, count: 6), volcanoRoot = 38
    var stormGain = 0.0, stormRate = 0.05
    var emberRate = 0.0, emberLevel = 0.07
    // magnetosphere
    var magGain = 0.0, magRatio = 1.414, glitterRate = 0.0
    // air
    var airGain = 0.0, airBP = 2000.0
    // Pulse
    var pulse = false, bpm = 120.0, swing = 0.0, hatP = 1.0, extraP = 0.0, ghost = 0.0, duck = 0.45, tideNorm = 0.0
    var groove = GrooveSteps(k: "x...x...x...x...", s: "....x.......x...", h: ".-x-.-x-.-x-.-x-", b: "..x...x...x...x.", bl: 1.6)
    var bassWave = 0 // 0 saw, 1 sine, 2 square
    // master
    var lowpass = 20000.0, drive = 0.0, ambientTrim = 1.0
}

private struct Smooth {
    var v: Double, target: Double, tau: Double
    init(_ v: Double, tau: Double) { self.v = v; target = v; self.tau = tau }
    @inline(__always) mutating func step(_ k: Double) -> Double { v += (target - v) * k; return v }
}

/// RBJ biquad (Web Audio BiquadFilterNode shapes)
private struct Biquad {
    enum Kind { case lp, hp, bp }
    var kind: Kind
    var b0 = 1.0, b1 = 0.0, b2 = 0.0, a1 = 0.0, a2 = 0.0
    var x1 = 0.0, x2 = 0.0, y1 = 0.0, y2 = 0.0
    init(_ k: Kind) { kind = k }
    mutating func set(_ f: Double, _ q: Double, _ sr: Double) {
        let w = 2 * Double.pi * clamp(f, 10, sr * 0.45) / sr, cw = cos(w), sw = sin(w), alpha = sw / (2 * max(0.0001, q))
        let a0 = 1 + alpha
        switch kind {
        case .lp: b0 = (1 - cw) / 2; b1 = 1 - cw; b2 = (1 - cw) / 2
        case .hp: b0 = (1 + cw) / 2; b1 = -(1 + cw); b2 = (1 + cw) / 2
        case .bp: b0 = alpha; b1 = 0; b2 = -alpha
        }
        a1 = -2 * cw; a2 = 1 - alpha
        b0 /= a0; b1 /= a0; b2 /= a0; a1 /= a0; a2 /= a0
    }
    @inline(__always) mutating func run(_ x: Double) -> Double {
        let y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
        x2 = x1; x1 = x; y2 = y1; y1 = y
        return y
    }
}

private struct Pink {
    var b0 = 0.0, b1 = 0.0, b2 = 0.0, seed: UInt32
    init(_ s: UInt32) { seed = s }
    @inline(__always) mutating func white() -> Double { seed = seed &* 1664525 &+ 1013904223; return Double(seed) / 2147483648.0 - 1 }
    @inline(__always) mutating func next() -> Double {
        let w = white()
        b0 = 0.99765 * b0 + w * 0.099; b1 = 0.963 * b1 + w * 0.2965; b2 = 0.57 * b2 + w * 1.0526
        return (b0 + b1 + b2 + w * 0.1848) * 0.18
    }
}

@inline(__always) private func polyBlep(_ t: Double, _ dt: Double) -> Double {
    if t < dt { let x = t / dt; return x + x - x * x - 1 }
    if t > 1 - dt { let x = (t - 1) / dt; return x * x + x + x + 1 }
    return 0
}
@inline(__always) private func saw(_ ph: Double, _ dt: Double) -> Double { 2 * ph - 1 - polyBlep(ph, dt) }
@inline(__always) private func square(_ ph: Double, _ dt: Double) -> Double {
    var p2 = ph + 0.5; if p2 >= 1 { p2 -= 1 }
    return (ph < 0.5 ? 1 : -1) + polyBlep(ph, dt) - polyBlep(p2, dt)
}
@inline(__always) private func tri(_ ph: Double) -> Double { let p = ph * 2 * .pi; return (sin(p) - sin(3 * p) / 9) * 0.81 * 1.12 }
@inline(__always) private func softCeil(_ x: Double) -> Double { let a = abs(x); return a <= 0.7 ? x : (x < 0 ? -1 : 1) * (0.7 + 0.28 * tanh((a - 0.7) / 0.28)) }
@inline(__always) private func panLR(_ p: Double) -> (Double, Double) { let a = (clamp(p, -1, 1) + 1) * .pi / 4; return (cos(a), sin(a)) }
@inline(__always) private func expEnv(_ amp: Double, _ floor: Double, _ t: Double, _ dur: Double) -> Double { amp * pow(floor / max(amp, 1e-9), t / max(0.001, dur)) }

/// FM quake instruments (js QINST): modulator ratio shallow / deep, index range, decay scale, upper partial
struct QuakeInstrument {
    let r: Double, r2: Double, idx: (Double, Double), dec: Double, p: Double, triangle: Bool
    static let all: [String: QuakeInstrument] = [
        "bell": .init(r: 2, r2: 1.4, idx: (1.5, 6), dec: 1, p: 4.007, triangle: false),
        "marimba": .init(r: 4, r2: 4, idx: (2, 4), dec: 0.35, p: 10, triangle: false),
        "glass": .init(r: 3.5, r2: 2.71, idx: (0.6, 2.5), dec: 1.6, p: 5.4, triangle: false),
        "gong": .init(r: 1.41, r2: 1.18, idx: (2, 7), dec: 1.9, p: 2.3, triangle: false),
        "pluck": .init(r: 1, r2: 1, idx: (3, 8), dec: 0.4, p: 3, triangle: true)]
}

/// One struck voice
private struct Voice {
    enum Kind: UInt8 { case fm, triBell, sub, rumble, pluck, ember, glitter, chime, kick, snare, hat, bass }
    var on = false
    var kind = Kind.fm
    var layer = 0
    var t = 0.0, delay = 0.0, dur = 1.0
    var f = 440.0, ratio = 2.0, idx0 = 1.0, idxDur = 1.0, p2 = 4.0, partial = 0.12
    var amp = 0.1, pl = 0.7, pr = 0.7
    var phC = 0.0, phM = 0.0, ph2 = 0.0, ph3 = 0.0
    var lp = Biquad(.lp), hp = Biquad(.hp), bp = Biquad(.bp)
    var f0 = 0.0, f1 = 0.0
    var flag = false, wave = 0
    var send = true // into the ping-pong delay
}

final class SynthDSP {
    let sr: Double
    private var lock = os_unfair_lock()
    private var pending = SynthTargets()
    private var pendingVoices: [Voice] = []
    private var tg = SynthTargets()
    private(set) var masterTarget = 0.0
    private var master = Smooth(0, tau: 0.3)
    /// Kick count, read by the visuals to breathe on the beat
    private(set) var kicks = 0
    private var fillPending = false

    // pad
    private var padPh = [Double](repeating: 0, count: 8)
    private var padF = (0..<4).map { _ in Smooth(110, tau: 0.12) }
    private var padVG = (0..<4).map { _ in Smooth(0.05, tau: 1) }
    private var padDet: [Double] = ([-7, 7, -7, 7, -7, 7, -7, 7] as [Double]).enumerated().map { i, d in d + Double((i * 37) % 5) - 2 }
    private var padCut = Smooth(800, tau: 1.5), padQ = Smooth(2, tau: 2), padG = Smooth(0, tau: 1), padLfoR = Smooth(0.07, tau: 2)
    private var padLP = Biquad(.lp), padLP2 = Biquad(.lp), padHP = Biquad(.hp), padHP2 = Biquad(.hp), padLfo = 0.0
    // surf
    private var surfN = Pink(7), surfBP = Biquad(.bp), surfLP = Biquad(.lp)
    private var surfG = Smooth(0, tau: 1), surfRate = Smooth(0.1, tau: 1), surfF = Smooth(700, tau: 2), surfPh = 0.0, surfPanPh = 0.0
    // shimmer
    private var shimPh = [0.0, 0, 0, 0], shimLfo = [0.0, 0, 0, 0], shimBPL = Biquad(.bp), shimBPR = Biquad(.bp)
    private var shimG = Smooth(0, tau: 1.2), shimF = Smooth(4000, tau: 2)
    private var shimFreq = [74, 81, 86, 93].map { Music.mtof($0) }
    private let shimPan = [-0.7, 0.7, -0.3, 0.3]
    // wind
    private var windN = Pink(11), windBP1 = Biquad(.bp), windBP2 = Biquad(.bp), windLfoPh = 0.0, windPanPh = 0.0
    private var windG = Smooth(0, tau: 1.5), windF1 = Smooth(600, tau: 2), windF2 = Smooth(1100, tau: 2), windLR = Smooth(0.09, tau: 2)
    // tide
    private var tidePh = [0.0, 0.0], tideLP = Biquad(.lp), tideG = Smooth(0, tau: 1), tideDet = Smooth(0, tau: 1), tideRoot = Smooth(50, tau: 0.5)
    // choir
    private var choirPh = [Double](repeating: 0, count: 10), choirF = (0..<10).map { _ in Smooth(220, tau: 1.2) }
    private var choirW = (0..<10).map { _ in Smooth(1, tau: 0.15) }
    private var choirG = Smooth(0, tau: 1.5)
    private var choirVibs = (0..<10).map { Double($0) * 0.137 }
    private let choirRate = (0..<10).map { 4.1 + Double(($0 * 7) % 10) * 0.14 }, choirDep = (0..<10).map { 3.0 + Double(($0 * 3) % 4) }
    private var formL1 = Biquad(.bp), formL2 = Biquad(.bp), formR1 = Biquad(.bp), formR2 = Biquad(.bp)
    private let choirPan: [Double] = EarthData.cities.map { clamp($0.lon / 180, -1, 1) * 0.8 }
    // space station beacon: a sine whose pitch follows latitude, with a slow vibrato
    private var issPh = 0.0, issVib = 0.0, issLP = Biquad(.lp), issF = Smooth(440, tau: 0.4), issG = Smooth(0, tau: 0.3), issP = Smooth(0, tau: 0.15)
    // natural events: volcano drone (6 saws), storm swirl (noise, swept band-pass), embers (scheduled grains)
    private var volPh = [Double](repeating: 0, count: 6), volG = (0..<6).map { _ in Smooth(0, tau: 2) }, volLP = Biquad(.lp), volRoot = Smooth(38, tau: 1)
    private let volSteps: [Double] = [0, 7, 12, -5, 3, 10]
    private var stormN = Pink(31), stormBP = Biquad(.bp), stormG = Smooth(0, tau: 2), stormR = Smooth(0.05, tau: 2), stormPh = 0.0, stormPanPh = 0.0
    private var nextEmber = 0.0, nextGlitter = 0.0, clockS = 0.0
    // magnetosphere: ring-modulated drone through a slowly sweeping band-pass, plus proton glitter
    private var magPhA = 0.0, magPhB = 0.0, magBP = Biquad(.bp), magG = Smooth(0, tau: 2), magR = Smooth(1.414, tau: 2), magSw = 0.0
    // air: breathy haze bed
    private var airN = Pink(41), airBP = Biquad(.bp), airG = Smooth(0, tau: 2), airF = Smooth(2000, tau: 2), airLfo = 0.0
    // Pulse sequencer
    private var seqCountdown = 0.0, seqStep = 0, fill = false
    private var duckEnv = 1.0, duckT = 10.0
    private var metalPh = [Double](repeating: 0, count: 6)
    private let metalF = [205.3, 304.4, 369.6, 522.7, 540, 800]
    private var metalBP = Biquad(.bp), metalHP = Biquad(.hp), metalLP = Biquad(.lp)
    // master tone
    private var mLPL = Biquad(.lp), mLPR = Biquad(.lp), mLPf = 20000.0
    // struck voices + ping-pong delay for quakes
    private var voices = [Voice](repeating: Voice(), count: 72)
    private var dl: [Float], dr: [Float], dIdx = 0, dLen: Int, dlLP = Biquad(.lp)
    private var rumble = Pink(23), rng = Pink(97)
    private var ctr = 0

    init(sampleRate: Double) {
        sr = sampleRate
        dLen = Int(sampleRate * 0.375)
        dl = [Float](repeating: 0, count: dLen); dr = [Float](repeating: 0, count: dLen)
        padHP.set(70, 0.707, sr); padHP2.set(70, 0.707, sr)
        surfLP.set(2500, 0.707, sr)
        tideLP.set(420, 0.5, sr)
        formL1.set(720, 3, sr); formR1.set(720, 3, sr); formL2.set(1150, 4, sr); formR2.set(1150, 4, sr)
        dlLP.set(3200, 0.707, sr)
        shimBPL.set(4000, 0.7, sr); shimBPR.set(4000, 0.7, sr)
        issLP.set(2400, 0.707, sr)
        volLP.set(260, 2.2, sr)
        metalBP.set(9000, 0.9, sr); metalHP.set(6500, 0.7, sr); metalLP.set(13000, 0.5, sr)
        mLPL.set(20000, 0.707, sr); mLPR.set(20000, 0.707, sr)
    }

    // MARK: control side (main thread)
    func update(_ t: SynthTargets) { os_unfair_lock_lock(&lock); pending = t; os_unfair_lock_unlock(&lock) }
    func setMaster(_ v: Double) { masterTarget = v }
    func triggerFill() { os_unfair_lock_lock(&lock); fillPending = true; os_unfair_lock_unlock(&lock) }

    /// js quakeVoice(): FM, depth picks the modulator ratio, magnitude sets brightness and length; M4.5+ adds a sub hit and rumble
    func quake(note: Int, vel: Int, mag: Double, depth: Double, pan: Double, inst: String = "bell", len: Double = 1, root: Int = Music.root, gain: Double = 1) {
        let I = QuakeInstrument.all[inst] ?? QuakeInstrument.all["bell"]!
        let f = Music.mtof(note), velN = Double(vel) / 127
        var v = Voice(); v.on = true; v.kind = .fm; v.f = f; v.layer = 0
        v.ratio = depth > 70 ? I.r2 : I.r; v.idx0 = mapv(mag, 1, 7, I.idx.0, I.idx.1); v.p2 = I.p
        v.dur = (1.2 + mag * 0.9) * len * I.dec; v.idxDur = v.dur * (I.triangle ? 0.15 : 0.6)
        v.amp = pow(velN, 1.6) * 0.55 * gain; v.flag = I.triangle
        (v.pl, v.pr) = panLR(pan)
        v.lp.set(mapv(Double(vel), 20, 127, 1800, 9000), 0.707, sr)
        var list = [v]
        if mag >= 4.5 {
            var s = Voice(); s.on = true; s.kind = .sub; s.layer = 0; s.f0 = Music.mtof(root - 12) * 2.2; s.f1 = Music.mtof(root - 12)
            s.amp = mapv(mag, 4.5, 8, 0.2, 0.34) * gain; s.dur = 1.5 + mag * 0.4; (s.pl, s.pr) = (0.7, 0.7); s.send = false; list.append(s)
            var n = Voice(); n.on = true; n.kind = .rumble; n.layer = 0; n.amp = mapv(mag, 4.5, 8, 0.35, 0.75) * gain; n.dur = mag * 0.9; (n.pl, n.pr) = (0.7, 0.7); n.send = false
            n.lp.set(160, 0.707, sr); n.hp.set(35, 0.6, sr); list.append(n) // 35-160 Hz: no sub-audible energy eating headroom
        }
        push(list)
    }
    /// js flareBell(): four bells a fifth/octave apart, root + 24
    func flare(root: Int = Music.root) {
        push([0, 7, 12, 19].enumerated().map { i, d in
            var v = Voice(); v.on = true; v.kind = .triBell; v.layer = 3; v.f = Music.mtof(root + 24 + d); v.delay = Double(i) * 0.12
            v.amp = 0.08; v.dur = 5; (v.pl, v.pr) = panLR([-0.4, 0.4, -0.15, 0.15][i]); return v
        })
    }
    /// js issPluck(): FM pluck every 5° of ground track; land crossings ring a brighter ratio
    func pluck(note: Int, vel: Int, pan: Double, land: Bool, inst: String = "pluck") {
        let f = Music.mtof(note)
        var v = Voice(); v.on = true; v.kind = .pluck; v.layer = 8; v.f = f; v.ratio = land ? 3 : 2
        v.idx0 = inst == "pluck" ? 2.5 : inst == "glass" ? 1.2 : 0.4
        v.amp = pow(Double(vel) / 127, 1.4) * 0.16 * (inst == "square" ? 0.5 : 1); v.dur = inst == "glass" ? 2.4 : 0.9
        v.flag = inst == "square"; (v.pl, v.pr) = panLR(pan)
        push([v])
    }
    /// js sunChime(): a rising (sunrise) or falling (sunset) triad
    func chime(note: Int, vel: Int, rise: Bool, pan: Double, third: Int, inst: String = "chime") {
        let steps = rise ? [0, third, 7] : [7, third, 0]
        push(steps.enumerated().map { i, s in
            var v = Voice(); v.on = true; v.kind = .chime; v.layer = 12; v.f = Music.mtof(note + s); v.delay = Double(i) * 0.11
            v.ratio = inst == "chime" ? 2.76 : 2; v.partial = inst == "soft" ? 0 : 0.35; v.flag = inst == "warm"
            v.amp = pow(Double(vel) / 127, 1.5) * 0.24; v.dur = 3.2; (v.pl, v.pr) = panLR(pan); return v
        })
    }
    private func push(_ v: [Voice]) { os_unfair_lock_lock(&lock); pendingVoices.append(contentsOf: v); os_unfair_lock_unlock(&lock) }

    // MARK: audio-thread voice makers
    private func degree(_ i: Int, base: Int) -> Int {
        let sc = tg.scale.isEmpty ? Music.majPent : tg.scale, n = sc.count
        let o = Int((Double(i) / Double(n)).rounded(.down))
        return base + 12 * o + sc[((i % n) + n) % n]
    }
    private func rand() -> Double { (rng.white() + 1) / 2 }
    private func add(_ v: Voice) {
        if let i = voices.firstIndex(where: { !$0.on }) { voices[i] = v }
        else if let i = voices.indices.max(by: { voices[$0].t < voices[$1].t }) { voices[i] = v }
    }
    private func ember(delay: Double, amp: Double) {
        let n = tg.scale.count
        var v = Voice(); v.on = true; v.kind = .ember; v.layer = 9; v.delay = delay
        v.f = Music.mtof(degree(7 + Int(rand() * Double(n) * 1.5), base: tg.root))
        v.amp = amp; v.dur = 0.22 + rand() * 0.38; v.f1 = 0.06 + rand() * 0.08
        v.bp.set(clamp(1800 * (0.75 + rand() * 0.5), 300, 8000), 2.5, sr)
        (v.pl, v.pr) = panLR(rand() * 1.4 - 0.7); v.send = false
        add(v)
    }
    private func glitter(delay: Double) {
        var v = Voice(); v.on = true; v.kind = .glitter; v.layer = 10; v.delay = delay
        v.f = Music.mtof(degree(8 + Int(rand() * 6), base: tg.root + 12)); v.amp = 0.05; v.dur = 0.18
        (v.pl, v.pr) = panLR(rand() * 2 - 1)
        add(v)
    }
    private func drum(_ kind: Voice.Kind, delay: Double, vel: Double, open: Bool = false) {
        var v = Voice(); v.on = true; v.kind = kind; v.layer = 7; v.delay = delay; v.amp = vel; v.send = false
        switch kind {
        case .kick: v.dur = 0.46; (v.pl, v.pr) = (0.707, 0.707); v.bp.set(3800, 0.8, sr)
        case .snare: v.dur = 0.22; (v.pl, v.pr) = (0.707, 0.707); v.hp.set(900, 0.6, sr); v.lp.set(7500, 0.707, sr); v.bp.set(4200, 0.9, sr)
        default: v.dur = open ? 0.27 : 0.05; v.flag = open; (v.pl, v.pr) = panLR(0.25); v.hp.set(8500, 0.707, sr)
        }
        add(v)
    }
    private func bass(note: Int, delay: Double, len: Double, lv: Double) {
        var v = Voice(); v.on = true; v.kind = .bass; v.layer = 7; v.delay = delay; v.f = Music.mtof(note); v.dur = len
        v.amp = 0.3 * lv * (tg.bassWave == 1 ? 1.4 : 1); v.wave = tg.bassWave; (v.pl, v.pr) = (0.707, 0.707); v.send = false
        add(v)
    }
    /// One 16th of the groove (js schedulePulse)
    private func step(delay: Double, st: Double) {
        let g = tg.groove, s16 = seqStep % 16, TR = g.trim
        let fillNow = fill && s16 >= 12
        let K = g.k[s16], Sn = g.s[s16], H = g.h[s16], B = g.b[s16]
        let tm = delay + (s16 % 2 == 1 ? tg.swing * st : 0)
        if K == 120 || K == 103 || (fillNow && s16 % 2 == 0) { // x g
            let v = fillNow ? 0.8 : K == 103 ? 0.5 : 1
            drum(.kick, delay: tm, vel: v * TR)
        }
        if Sn == 120 { drum(.snare, delay: tm, vel: TR) } // x
        else if Sn == 114 { drum(.snare, delay: tm, vel: 0.32) } // r
        else if Sn == 103 || (tg.ghost > 0 && rand() < tg.ghost) { drum(.snare, delay: tm, vel: 0.25) }
        if H != 46 {
            if rand() < tg.hatP {
                let op = H == 111, v = (H == 45 ? 0.35 + rand() * 0.15 : 0.6 + rand() * 0.4) * (K == 120 ? 0.6 : 1) * (op ? 0.8 : 1)
                drum(.hat, delay: tm, vel: v * TR, open: op)
            }
        } else if tg.extraP > 0 && rand() < tg.extraP { drum(.hat, delay: tm, vel: 0.3) }
        if B != 46 {
            let i0 = jsRound(mapv(tg.tideNorm, -1, 1, 0, 4))
            let bn = degree(B == 102 ? i0 + 2 : i0, base: tg.root - 24) + (B == 111 ? 12 : 0)
            bass(note: bn, delay: tm, len: st * g.bl, lv: (K == 120 ? 0.65 : 1) * TR)
        }
        if s16 == 15 { fill = false }
        seqStep += 1
    }

    // MARK: audio thread
    func render(_ L: UnsafeMutablePointer<Float>, _ R: UnsafeMutablePointer<Float>, _ n: Int) {
        if os_unfair_lock_trylock(&lock) {
            tg = pending
            if fillPending { fill = true; fillPending = false }
            if !pendingVoices.isEmpty {
                for nv in pendingVoices { add(nv) }
                pendingVoices.removeAll(keepingCapacity: true)
            }
            os_unfair_lock_unlock(&lock)
        }
        let dt = 1 / sr
        let k = { (tau: Double) in 1 - exp(-dt / tau) }
        let kPad = k(0.12), kChoirF = k(0.35), kPadV = k(1), kCut = k(1.5), kQ = k(2), kG1 = k(1), kG15 = k(1.5), kG12 = k(1.2), kF2 = k(2), kMaster = k(0.3)
        let kF04 = k(0.4), kG03 = k(0.3), kP015 = k(0.15), kG05 = k(0.5)
        let vol = tg.vol
        for i in 0..<4 { padF[i].target = tg.padFreqs[i]; padVG[i].target = tg.padVoiceGain[i] }
        padCut.target = tg.padCut; padQ.target = tg.padQ; padG.target = tg.padGain * vol[1]; padLfoR.target = tg.padLfoRate
        surfG.target = tg.surfGain * vol[2]; surfRate.target = tg.surfRate; surfF.target = tg.surfBP
        shimG.target = tg.shimGain * vol[3]; shimF.target = tg.shimBP
        windG.target = tg.windGain * vol[4]; windF1.target = tg.windBP1; windF2.target = tg.windBP2; windLR.target = tg.windLfo
        tideG.target = tg.tideGain * vol[5]; tideDet.target = tg.tideDetune; tideRoot.target = Double(tg.root)
        choirG.target = tg.choirGain * vol[6]
        for i in 0..<10 { choirF[i].target = tg.choirFreqs[i]; choirW[i].target = tg.choirVoice[i] }
        issF.target = tg.issFreq; issG.target = tg.issGain * vol[8]; issP.target = tg.issPan
        for i in 0..<6 { volG[i].target = tg.volcanoGains[i] * vol[9] }
        volRoot.target = Double(tg.volcanoRoot)
        stormG.target = tg.stormGain * vol[9]; stormR.target = tg.stormRate
        magG.target = tg.magGain * vol[10]; magR.target = tg.magRatio
        airG.target = tg.airGain * vol[11]; airF.target = tg.airBP
        master.target = masterTarget
        let shimRoot = Double(tg.root)
        for (i, st) in [24.0, 31, 36, 43].enumerated() { shimFreq[i] = Music.mtof(shimRoot + st) }
        if abs(tg.lowpass - mLPf) > 1 { mLPf = tg.lowpass; mLPL.set(mLPf, 0.707, sr); mLPR.set(mLPf, 0.707, sr) }
        let useLP = mLPf < 19000
        let drive = tg.drive

        // stochastic grains: schedule the next 0.15 s of embers and glitter (Poisson, like the site)
        let bufDur = Double(n) * dt
        if tg.emberRate > 0.01 && vol[9] > 0.001 {
            let rate = tg.emberRate, lv = tg.emberLevel
            if nextEmber < clockS { nextEmber = clockS }
            while nextEmber < clockS + bufDur + 0.15 {
                nextEmber += -log(max(1e-6, 1 - rand())) / rate
                ember(delay: max(0, nextEmber - clockS), amp: lv * (0.5 + rand() * 0.6) * vol[9])
            }
        } else { nextEmber = clockS }
        if tg.glitterRate > 0.01 && vol[10] > 0.001 {
            if nextGlitter < clockS { nextGlitter = clockS }
            while nextGlitter < clockS + bufDur + 0.15 {
                nextGlitter += -log(max(1e-6, 1 - rand())) / tg.glitterRate
                glitter(delay: max(0, nextGlitter - clockS))
            }
        } else { nextGlitter = clockS }
        // Pulse: sample-accurate 16ths
        let st = 60 / max(40, tg.bpm) / 4
        if tg.pulse {
            var off = seqCountdown
            while off < bufDur { step(delay: off, st: st); off += st }
            seqCountdown = off - bufDur
        } else { seqCountdown = 0; seqStep = 0 }
        clockS += bufDur
        let anyHat = voices.contains { $0.on && $0.kind == .hat }
        let duckAmt = tg.pulse ? tg.duck : 0

        for s in 0..<n {
            if ctr & 31 == 0 {
                let lfo = pow(2, 0.5 * sin(padLfo * 2 * .pi))
                padLP.set(padCut.v * lfo, padQ.v, sr); padLP2.set(padCut.v * lfo, padQ.v, sr)
                surfBP.set(surfF.v * pow(2, 0.58 * sin(surfPh * 2 * .pi)), 0.6, sr)
                let wl = sin(windLfoPh * 2 * .pi) * 220
                windBP1.set(windF1.v + wl, 5, sr); windBP2.set(windF2.v + wl, 9, sr)
                shimBPL.set(shimF.v, 0.7, sr); shimBPR.set(shimF.v, 0.7, sr)
                stormBP.set(max(80, 400 + 300 * sin(stormPh * 2 * .pi)), 2, sr)
                magBP.set(max(120, 900 + 500 * sin(magSw * 2 * .pi)), 1.5, sr)
                airBP.set(airF.v, 0.8, sr)
                for i in voices.indices where voices[i].on && voices[i].kind == .bass {
                    let v = voices[i], t = max(0, v.t - v.delay)
                    voices[i].lp.set(900 * pow(140 / 900, min(1, t / max(0.01, v.dur))), 5, sr)
                }
            }
            ctr &+= 1
            // sidechain duck from the kick
            duckT += dt
            duckEnv = duckT < 0.05 ? 1 - duckAmt : 1 - duckAmt * exp(-(duckT - 0.05) / 0.11)
            var l = 0.0, r = 0.0

            // solar wind pad: 4 chord tones × 2 detuned oscillators
            let pg = padG.step(kG1)
            if pg > 0.0005 {
                var pl = 0.0, pr = 0.0
                for v in 0..<4 {
                    let f = padF[v].step(kPad), vg = padVG[v].step(kPadV)
                    for d in 0..<2 {
                        let j = v * 2 + d, fr = f * pow(2, padDet[j] / 1200), inc = fr * dt
                        padPh[j] += inc; if padPh[j] >= 1 { padPh[j] -= 1 }
                        let osc: Double = switch tg.padWave { case 1: square(padPh[j], inc) * 0.7; case 2: tri(padPh[j]); case 3: sin(padPh[j] * 2 * .pi); default: saw(padPh[j], inc) }
                        let x = osc * vg
                        if d == 0 { pl += x * 0.8; pr += x * 0.35 } else { pl += x * 0.35; pr += x * 0.8 }
                    }
                }
                l += padHP.run(padLP.run(pl)) * pg * duckEnv; r += padHP2.run(padLP2.run(pr)) * pg * duckEnv
            } else { for v in 0..<4 { _ = padF[v].step(kPad); _ = padVG[v].step(kPadV) } }
            _ = padCut.step(kCut); _ = padQ.step(kQ)
            padLfo += padLfoR.step(kQ) * dt; if padLfo >= 1 { padLfo -= 1 }

            // ocean surf
            let sg = surfG.step(kG1); _ = surfF.step(kF2)
            surfPh += surfRate.step(kG1) * dt; if surfPh >= 1 { surfPh -= 1 }
            surfPanPh += 0.031 * dt; if surfPanPh >= 1 { surfPanPh -= 1 }
            if sg > 0.0005 {
                let x = surfLP.run(surfBP.run(surfN.next())) * (0.5 + 0.5 * sin(surfPh * 2 * .pi)) * sg * 2.2 * duckEnv
                let (a, b) = panLR(0.6 * sin(surfPanPh * 2 * .pi)); l += x * a; r += x * b
            }

            // X-ray shimmer
            let xg = shimG.step(kG12); _ = shimF.step(kF2)
            if xg > 0.0005 {
                var xl = 0.0, xr = 0.0
                for i in 0..<4 {
                    shimPh[i] += shimFreq[i] * dt; if shimPh[i] >= 1 { shimPh[i] -= 1 }
                    shimLfo[i] += (0.13 + Double(i) * 0.07) * dt; if shimLfo[i] >= 1 { shimLfo[i] -= 1 }
                    let x = sin(shimPh[i] * 2 * .pi) * 0.05 * sin(shimLfo[i] * 2 * .pi)
                    let (a, b) = panLR(shimPan[i]); xl += x * a; xr += x * b
                }
                l += shimBPL.run(xl) * xg * 3; r += shimBPR.run(xr) * xg * 3
            }

            // jet stream
            let wg = windG.step(kG15); _ = windF1.step(kF2); _ = windF2.step(kF2)
            windLfoPh += windLR.step(kF2) * dt; if windLfoPh >= 1 { windLfoPh -= 1 }
            windPanPh += 0.05 * dt; if windPanPh >= 1 { windPanPh -= 1 }
            if wg > 0.0005 {
                let nz = windN.next(), x = (windBP1.run(nz) + windBP2.run(nz)) * wg * 1.5 * duckEnv
                let (a, b) = panLR(0.8 * sin(windPanPh * 2 * .pi)); l += x * a; r += x * b
            }

            // tides
            let tgn = tideG.step(kG1), det = pow(2, tideDet.step(kG1) / 1200), troot = tideRoot.step(kG05)
            tidePh[0] += Music.mtof(troot - 12) * det * dt; if tidePh[0] >= 1 { tidePh[0] -= 1 }
            tidePh[1] += Music.mtof(troot) * det * dt; if tidePh[1] >= 1 { tidePh[1] -= 1 }
            if tgn > 0.0005 {
                let x = tideLP.run(sin(tidePh[0] * 2 * .pi) + 0.35 * sin(tidePh[1] * 2 * .pi)) * tgn
                l += x; r += x
            }

            // planet chord
            let cg = choirG.step(kG15)
            if cg > 0.0005 {
                var cl = 0.0, cr = 0.0
                for i in 0..<10 {
                    let inc = choirF[i].step(kChoirF) * pow(2, choirDep[i] * sin(choirVibs[i] * 2 * .pi) / 1200) * dt
                    choirVibs[i] += choirRate[i] * dt; if choirVibs[i] >= 1 { choirVibs[i] -= 1 }
                    choirPh[i] += inc; if choirPh[i] >= 1 { choirPh[i] -= 1 }
                    let x = saw(choirPh[i], inc) * 0.022 * choirW[i].step(kP015)
                    let (a, b) = panLR(choirPan[i]); cl += x * a; cr += x * b
                }
                l += (formL1.run(cl) + formL2.run(cl) + cl * 0.35) * cg * duckEnv
                r += (formR1.run(cr) + formR2.run(cr) + cr * 0.35) * cg * duckEnv
            } else { for i in 0..<10 { _ = choirF[i].step(kChoirF) } }

            // space station beacon
            let ig = issG.step(kG03), ifr = issF.step(kF04), ip = issP.step(kP015)
            issVib += 5.5 * dt; if issVib >= 1 { issVib -= 1 }
            issPh += ifr * pow(2, 6 * sin(issVib * 2 * .pi) / 1200) * dt; if issPh >= 1 { issPh -= 1 }
            if ig > 0.0005 {
                let x = issLP.run(sin(issPh * 2 * .pi)) * ig
                let (a, b) = panLR(ip); l += x * a; r += x * b
            }

            // volcano drone + storm swirl
            let vr = volRoot.step(kG1)
            var vsum = 0.0
            for i in 0..<6 {
                let g = volG[i].step(kF2)
                let inc = Music.mtof(vr + volSteps[i]) * pow(2, (Double(i) - 2.5) * 9 / 1200) * dt
                volPh[i] += inc; if volPh[i] >= 1 { volPh[i] -= 1 }
                if g > 0.0001 { vsum += saw(volPh[i], inc) * g }
            }
            if vsum != 0 { let x = volLP.run(vsum) * 0.9; l += x; r += x } else { _ = volLP.run(0) }
            let sgn = stormG.step(kF2)
            stormPh += stormR.step(kF2) * dt; if stormPh >= 1 { stormPh -= 1 }
            stormPanPh += 0.13 * dt; if stormPanPh >= 1 { stormPanPh -= 1 }
            if sgn > 0.0005 {
                let x = stormBP.run(stormN.next()) * sgn * 3
                let (a, b) = panLR(0.9 * sin(stormPanPh * 2 * .pi)); l += x * a; r += x * b
            }

            // magnetosphere ring-mod drone
            let mg = magG.step(kF2), mr = magR.step(kF2)
            magSw += 0.03 * dt; if magSw >= 1 { magSw -= 1 }
            let mf = Music.mtof(tideRoot.v)
            magPhA += mf * dt; if magPhA >= 1 { magPhA -= 1 }
            magPhB += mf * mr * dt; if magPhB >= 1 { magPhB -= 1 }
            if mg > 0.0005 {
                let x = magBP.run(sin(magPhA * 2 * .pi) * sin(magPhB * 2 * .pi)) * mg
                l += x; r += x
            }

            // air haze bed
            let ag = airG.step(kF2); _ = airF.step(kF2)
            airLfo += 0.11 * dt; if airLfo >= 1 { airLfo -= 1 }
            if ag > 0.0005 {
                let x = airBP.run(airN.next()) * (0.7 + 0.3 * sin(airLfo * 2 * .pi)) * ag * 2
                l += x * 0.9; r += x
            }

            // shared hat metal (six inharmonic squares)
            var metal = 0.0
            if anyHat {
                var m = 0.0
                for i in 0..<6 {
                    let inc = metalF[i] * dt
                    metalPh[i] += inc; if metalPh[i] >= 1 { metalPh[i] -= 1 }
                    m += square(metalPh[i], inc)
                }
                metal = metalLP.run(metalHP.run(metalBP.run(m * 0.16)))
            }

            // struck voices
            var ql = 0.0, qr = 0.0, sendL = 0.0, sendR = 0.0
            for i in 0..<voices.count where voices[i].on {
                voices[i].t += dt
                let v = voices[i], t = v.t - v.delay
                if t < 0 { continue }
                if t > v.dur + 0.1 { voices[i].on = false; continue }
                var x = 0.0
                switch v.kind {
                case .fm:
                    let env = t < 0.005 ? v.amp * t / 0.005 : expEnv(v.amp, 0.0005, t - 0.005, v.dur - 0.005)
                    let idx = v.f * v.idx0 * pow(0.02 / v.idx0, min(1, t / v.idxDur))
                    voices[i].phM += v.f * v.ratio * dt; if voices[i].phM >= 1 { voices[i].phM -= 1 }
                    let fm = idx * sin(voices[i].phM * 2 * .pi)
                    voices[i].phC += (v.f + fm) * dt; voices[i].phC -= voices[i].phC.rounded(.down)
                    voices[i].ph2 += v.f * v.p2 * dt; if voices[i].ph2 >= 1 { voices[i].ph2 -= 1 }
                    let partial = expEnv(v.amp * 0.12, 0.0001, min(t, v.dur * 0.35), v.dur * 0.35)
                    let car = v.flag ? tri(voices[i].phC) : sin(voices[i].phC * 2 * .pi)
                    x = voices[i].lp.run(car * env) + sin(voices[i].ph2 * 2 * .pi) * partial
                case .triBell:
                    let env = t < 0.02 ? v.amp * t / 0.02 : expEnv(v.amp, 0.0003, t - 0.02, v.dur - 0.02)
                    voices[i].phC += v.f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    x = tri(voices[i].phC) * env
                case .sub:
                    let f = t < 0.35 ? v.f0 * pow(v.f1 / v.f0, t / 0.35) : v.f1
                    let env = t < 0.01 ? v.amp * t / 0.01 : expEnv(v.amp, 0.0005, t - 0.01, v.dur)
                    voices[i].phC += f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    x = sin(voices[i].phC * 2 * .pi) * env
                case .rumble:
                    let env = t < 0.08 ? v.amp * t / 0.08 : expEnv(v.amp, 0.0005, t - 0.08, max(0.1, v.dur - 0.08))
                    x = voices[i].lp.run(voices[i].hp.run(rumble.white())) * env * 2.2
                case .pluck:
                    let env = t < 0.004 ? v.amp * t / 0.004 : expEnv(v.amp, 0.0004, t - 0.004, v.dur)
                    let idx = v.f * v.idx0 * pow(0.01 / v.idx0, min(1, t / 0.25))
                    voices[i].phM += v.f * v.ratio * dt; if voices[i].phM >= 1 { voices[i].phM -= 1 }
                    voices[i].phC += (v.f + idx * sin(voices[i].phM * 2 * .pi)) * dt; voices[i].phC -= voices[i].phC.rounded(.down)
                    x = (v.flag ? (voices[i].phC < 0.5 ? 0.6 : -0.6) : sin(voices[i].phC * 2 * .pi)) * env
                case .ember:
                    let env = t < 0.006 ? v.amp * t / 0.006 : t < v.dur ? expEnv(v.amp, v.amp * 0.004, t - 0.006, v.dur - 0.006) : 0
                    voices[i].phC += v.f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    let nenv = t < 0.008 ? v.amp * 1.6 * t / 0.008 : t < v.f1 ? expEnv(v.amp * 1.6, v.amp * 0.01, t - 0.008, v.f1 - 0.008) : 0
                    x = sin(voices[i].phC * 2 * .pi) * env + voices[i].bp.run(rumble.white()) * nenv
                case .glitter:
                    let env = t < 0.002 ? v.amp * t / 0.002 : expEnv(v.amp, 0.0003, t - 0.002, v.dur - 0.002)
                    voices[i].phC += v.f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    x = sin(voices[i].phC * 2 * .pi) * env
                case .chime:
                    let env = t < 0.01 ? v.amp * t / 0.01 : expEnv(v.amp, 0.0004, t - 0.01, v.dur)
                    voices[i].phC += v.f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    voices[i].ph2 += v.f * v.ratio * dt; if voices[i].ph2 >= 1 { voices[i].ph2 -= 1 }
                    x = ((v.flag ? tri(voices[i].phC) : sin(voices[i].phC * 2 * .pi)) + sin(voices[i].ph2 * 2 * .pi) * v.partial) * env
                case .kick:
                    if t < dt * 1.5 { duckT = 0; kicks &+= 1 }
                    let f = 155 * pow(42.0 / 155, min(1, t / 0.12))
                    voices[i].phC += f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    let env = t < 0.0015 ? 0.95 * v.amp * t / 0.0015 : t < 0.45 ? expEnv(0.95 * v.amp, 0.001, t - 0.0015, 0.45) : 0
                    let cenv = t < 0.0008 ? 0.2 * v.amp * t / 0.0008 : t < 0.012 ? expEnv(0.2 * v.amp, 0.001, t - 0.0008, 0.0112) : 0
                    x = sin(voices[i].phC * 2 * .pi) * env + (cenv > 0 ? voices[i].bp.run(rumble.white()) * cenv : 0)
                case .snare:
                    let nenv = t < 0.0012 ? 0.55 * v.amp * t / 0.0012 : (0.18 * v.amp + 0.37 * v.amp * exp(-(t - 0.0012) / 0.018)) * pow(0.001 / 0.18, min(1, t / 0.2))
                    let nz = voices[i].lp.run(voices[i].hp.run(rumble.white()))
                    let crack = voices[i].bp.run(nz) * 0.8
                    voices[i].phC += 190 * pow(150.0 / 190, min(1, t / 0.05)) * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    voices[i].ph2 += 330 * pow(280.0 / 330, min(1, t / 0.05)) * dt; if voices[i].ph2 >= 1 { voices[i].ph2 -= 1 }
                    let b1 = t < 0.11 ? expEnv(0.34 * v.amp, 0.001, t, 0.11) : 0, b2 = t < 0.06 ? expEnv(0.12 * v.amp, 0.001, t, 0.06) : 0
                    x = (nz + crack) * nenv + sin(voices[i].phC * 2 * .pi) * b1 + sin(voices[i].ph2 * 2 * .pi) * b2
                case .hat:
                    let d = v.flag ? 0.26 : 0.045
                    let env = t < 0.0008 ? 0.18 * v.amp * t / 0.0008 : t < d ? expEnv(0.18 * v.amp, 0.001, t - 0.0008, d) : 0
                    let nenv = t < 0.0008 ? 0.05 * v.amp * t / 0.0008 : t < (v.flag ? 0.2 : 0.035) ? expEnv(0.05 * v.amp, 0.001, t, v.flag ? 0.2 : 0.035) : 0
                    x = metal * env * 6 + voices[i].hp.run(rumble.white()) * nenv
                case .bass:
                    let env = t < 0.004 ? v.amp * t / 0.004 : t < v.dur ? expEnv(v.amp, 0.001, t - 0.004, v.dur) : 0
                    let inc = v.f * dt
                    voices[i].phC += inc; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    voices[i].ph2 += inc * 0.5; if voices[i].ph2 >= 1 { voices[i].ph2 -= 1 }
                    let o1: Double = v.wave == 1 ? sin(voices[i].phC * 2 * .pi) : v.wave == 2 ? square(voices[i].phC, inc) : saw(voices[i].phC, inc)
                    x = voices[i].lp.run(o1 + square(voices[i].ph2, inc * 0.5) * 0.35) * env
                }
                let lv = vol[v.layer]
                if lv < 0.0001 { continue }
                x *= lv
                if v.layer == 0 || v.layer == 3 { ql += x * v.pl; qr += x * v.pr }
                else { l += x * v.pl; r += x * v.pr }
                if v.send && v.layer != 0 { sendL += x * v.pl * 0.5; sendR += x * v.pr * 0.5 }
            }
            // ping-pong delay on the quake bells (and a little of the station, glitter and chimes)
            let dOutL = Double(dl[dIdx]), dOutR = Double(dr[dIdx])
            let fbIn = dlLP.run(dOutL)
            dl[dIdx] = Float((ql + sendL) * 0.3 + dOutR * 0.38)
            dr[dIdx] = Float(fbIn + sendR * 0.3)
            dIdx += 1; if dIdx >= dLen { dIdx = 0 }
            l += ql + dOutL; r += qr + dOutR

            if useLP { l = mLPL.run(l); r = mLPR.run(r) }
            if drive > 0.01 { let g = 1 + drive * 4, k = (1 + drive * 0.5) / g; l = tanh(l * g) * k; r = tanh(r * g) * k } // tape-style saturation, unity-ish at low level
            let m = master.step(kMaster) * 0.72 * 0.99 * tg.ambientTrim
            L[s] = Float(softCeil(l * m)); R[s] = Float(softCeil(r * m))
        }
    }
}
